package org.mockito.internal.matchers;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Equality_areEqual_TriageGen0Test {

    @Test
    public void testAreEqual_BothNull() {
        assertTrue(Equality.areEqual(null, null));
    }

    @Test
    public void testAreEqual_FirstNull() {
        assertFalse(Equality.areEqual(null, new Object()));
    }

    @Test
    public void testAreEqual_SecondNull() {
        assertFalse(Equality.areEqual(new Object(), null));
    }

    @Test
    public void testAreEqual_BothArrays_Equal() {
        // Assuming isArray and areArraysEqual are accessible and work as standard array checks
        Integer[] arr1 = {1, 2, 3};
        Integer[] arr2 = {1, 2, 3};
        assertTrue(Equality.areEqual(arr1, arr2));
    }

    @Test
    public void testAreEqual_FirstIsArray_SecondIsNotArray() {
        Integer[] arr1 = {1, 2, 3};
        String str2 = "not an array";
        assertFalse(Equality.areEqual(arr1, str2));
    }

    @Test
    public void testAreEqual_BothArrays_NotEqual() {
        Integer[] arr1 = {1, 2, 3};
        Integer[] arr2 = {1, 2, 4};
        assertFalse(Equality.areEqual(arr1, arr2));
    }

    @Test
    public void testAreEqual_NotArrays_Equal() {
        String s1 = "hello";
        String s2 = "hello";
        assertTrue(Equality.areEqual(s1, s2));
    }

    @Test
    public void testAreEqual_NotArrays_NotEqual() {
        String s1 = "hello";
        String s2 = "world";
        assertFalse(Equality.areEqual(s1, s2));
    }

    @Test
    public void testAreEqual_NotArrays_DifferentTypes() {
        Integer i = 1;
        String s = "1";
        assertFalse(Equality.areEqual(i, s));
    }
}
